#include "logos_court.h"
#include <fstream>
#include <iostream>
namespace logos {static Status read_exact(const std::filesystem::path&p,Buffer*out){std::ifstream f(p,std::ios::binary);if(!f)return Status::IOError;f.seekg(0,std::ios::end);auto n=f.tellg();if(n<0)return Status::IOError;f.seekg(0);out->resize((size_t)n);if(n&&!f.read((char*)out->data(),(std::streamsize)n))return Status::IOError;return Status::Ok;}static Status init_root(const std::filesystem::path&r){ObjectStore s{};Ledger l{};auto st=object_store_open(r/"objects",&s);if(st!=Status::Ok)return st;std::error_code ec;std::filesystem::create_directories(r/"projection",ec);std::filesystem::create_directories(r/"views",ec);std::filesystem::create_directories(r/"receipts",ec);if(ec)return Status::IOError;return ledger_open(r/"ledger"/"events.lgl",&l);}static Status load_graph(const std::filesystem::path&r,ObjectStore*s,Ledger*l,GraphState*g){auto st=object_store_open(r/"objects",s);if(st!=Status::Ok)return st;if((st=ledger_open(r/"ledger"/"events.lgl",l))!=Status::Ok)return st;return graph_replay(s,*l,g);}}
int main(int argc,char**argv){using namespace logos;if(argc<3){std::cerr<<"usage: logos <init|ingest-historical|ingest-genesis|project|view|verify|court> <root> [file|canon|proof]\n";return 2;}std::string cmd=argv[1];std::filesystem::path root=argv[2];Status st=Status::Ok;if(cmd=="init")st=init_root(root);else if(cmd=="ingest-historical"||cmd=="ingest-genesis"){if(argc!=4)return 2;ObjectStore s{};Ledger l{};GraphState g{};if((st=load_graph(root,&s,&l,&g))==Status::Ok){Buffer b;if((st=read_exact(argv[3],&b))==Status::Ok){CompilerCapsule c{};st=cmd=="ingest-historical"?ingest_historical(&s,&l,&g,{b.data(),(u64)b.size()},&c):ingest_genesis(&s,&l,&g,{b.data(),(u64)b.size()},&c);if(st==Status::Ok)std::cout<<"graph_root="<<hex(c.graph_root_after)<<" disposition="<<(u64)c.disposition<<"\n";}}}else if(cmd=="project"){ObjectStore s{};Ledger l{};GraphState g{};if((st=load_graph(root,&s,&l,&g))==Status::Ok){Digest256 d{};graph_root(g,&d);std::error_code ec;std::filesystem::create_directories(root/"projection",ec);std::ofstream f(root/"projection"/"graph.txt");f<<"graph_root="<<hex(d)<<"\nnodes="<<g.nodes.size()<<"\nedges="<<g.edges.size()<<"\n";st=f?Status::Ok:Status::IOError;}}else if(cmd=="view"){if(argc!=4)return 2;ObjectStore s{};Ledger l{};GraphState g{};if((st=load_graph(root,&s,&l,&g))==Status::Ok){Digest256 d{};st=std::string(argv[3])=="canon"?compile_canon_view(&g,&s,&l,&d):std::string(argv[3])=="proof"?compile_proof_view(&g,&s,&l,"IMP-GENESIS-MVS-001",&d):Status::InvalidArgument;if(st==Status::Ok)std::cout<<hex(d)<<"\n";}}else if(cmd=="verify"){Digest256 g{},c{},p{};st=verify_root(root,&g,&c,&p);if(st==Status::Ok)std::cout<<"graph="<<hex(g)<<" canon="<<hex(c)<<" proof="<<hex(p)<<"\n";}else if(cmd=="court"){CourtSummary a{},b{};st=run_graph_court(root/"graph-court",&a);if(st==Status::Ok)st=run_compiler_court(root/"compiler-court",&b);if(st==Status::Ok&&a.passed==18&&b.passed==20)st=run_mevs_acceptance(root/"acceptance");std::cout<<"LOGOS_COURT graph="<<a.passed<<"/"<<a.discovered<<" compiler="<<b.passed<<"/"<<b.discovered<<" status="<<status_name(st)<<"\n";}else return 2;if(st!=Status::Ok){std::cerr<<status_name(st)<<"\n";return 1;}return 0;}
